import type { Transition } from "motion/react";

export const easeOut = [0.23, 1, 0.32, 1] as const;

export const easeInOut = [0.77, 0, 0.175, 1] as const;

export const easeOutClass = "ease-[cubic-bezier(0.23,1,0.32,1)]";

export const duration = {
  fast: 0.14,
  base: 0.2,
  slow: 0.28,
} as const;

export const springSnappy = {
  type: "spring",
  duration: 0.24,
  bounce: 0,
} as const satisfies Transition;

export const springLayout = {
  type: "spring",
  duration: 0.3,
  bounce: 0,
} as const satisfies Transition;

export function transitionFor(
  reduceMotion: boolean | null,
  transition: Transition,
): Transition {
  return reduceMotion ? { duration: 0 } : transition;
}

import { type CnOptions, cn as mergeClasses } from "tailwind-variants";

export function cn(...classes: CnOptions): string {
  return mergeClasses(...classes) ?? "";
}

"use client";

import { CheckIcon } from "@phosphor-icons/react";
import { motion, useReducedMotion } from "motion/react";
import {
  ListBox as AriaListBox,
  ListBoxItem as AriaListBoxItem,
  composeRenderProps,
  type ListBoxItemProps,
  type ListBoxProps,
} from "react-aria-components";
import { duration, easeOut } from "./motion";
import { cn } from "./utils";

export function ListBox<T extends object>({
  className,
  ...props
}: ListBoxProps<T>) {
  return (
    <AriaListBox
      {...props}
      data-slot="list-box"
      className={composeRenderProps(className, (className) =>
        cn(
          "grid max-h-72 w-full min-w-0 gap-1 overflow-y-auto overscroll-contain rounded-lg border border-border bg-card p-1.5 shadow-[var(--shadow-card)] outline-none empty:min-h-24 empty:place-items-center empty:text-sm empty:text-muted-foreground focus-visible:outline-2 focus-visible:outline-solid focus-visible:outline-offset-2 focus-visible:outline-ring",
          className,
        ),
      )}
    />
  );
}

export function ListBoxItem({
  className,
  children,
  ...props
}: ListBoxItemProps) {
  return (
    <AriaListBoxItem
      {...props}
      data-slot="list-box-item"
      textValue={
        props.textValue ?? (typeof children === "string" ? children : undefined)
      }
      className={composeRenderProps(className, (className) =>
        cn(
          "group/item flex min-h-11 min-w-0 cursor-pointer items-center justify-between gap-3 rounded-md px-3 py-2 text-sm text-foreground outline-none [overflow-wrap:anywhere] hover:bg-muted focus:bg-muted selected:bg-accent selected:text-accent-foreground disabled:cursor-default disabled:opacity-50 focus-visible:outline-1 focus-visible:outline-solid focus-visible:-outline-offset-1 focus-visible:outline-ring forced-colors:focus-visible:outline-2 forced-colors:focus-visible:-outline-offset-2",
          className,
        ),
      )}
    >
      {composeRenderProps(children, (content, { isSelected }) => (
        <>
          {content}
          <SelectionMark isSelected={isSelected} />
        </>
      ))}
    </AriaListBoxItem>
  );
}

export function SelectionMark({
  isSelected,
  className,
}: {
  isSelected: boolean;
  className?: string;
}) {
  const reduceMotion = useReducedMotion();
  return (
    <motion.span
      aria-hidden="true"
      className={cn("ms-auto shrink-0", className)}
      initial={false}
      animate={{ opacity: isSelected ? 1 : 0, scale: isSelected ? 1 : 0.85 }}
      transition={{ duration: reduceMotion ? 0 : duration.fast, ease: easeOut }}
    >
      <CheckIcon size={16} weight="bold" />
    </motion.span>
  );
}

"use client";

import {
  Dialog as AriaDialog,
  type DialogProps as AriaDialogProps,
  Popover as AriaPopover,
  type PopoverProps as AriaPopoverProps,
  composeRenderProps,
  DialogTrigger,
  type DialogTriggerProps,
  Heading,
  type HeadingProps,
  OverlayArrow,
  type OverlayArrowProps,
  Text,
  type TextProps,
} from "react-aria-components";
import { cn } from "./utils";

export interface PopoverProps extends AriaPopoverProps {
  "data-slot"?: string;
}

export function PopoverTrigger(props: DialogTriggerProps) {
  return <DialogTrigger {...props} />;
}

export function Popover({
  className,
  "data-slot": dataSlot = "popover",
  ...props
}: PopoverProps) {
  return (
    <AriaPopover
      {...props}
      data-slot={dataSlot}
      className={composeRenderProps(className, (className) =>
        cn(
          "max-w-[calc(100vw-2rem)] overflow-auto overscroll-contain rounded-xl border border-border bg-popover p-4 text-popover-foreground [overflow-wrap:anywhere] shadow-[var(--shadow-float)] outline-none",
          // An arrow sits outside the panel, so the panel stops clipping.
          "has-[[data-slot=popover-arrow]]:overflow-visible",
          // React Aria sets data-entering and data-exiting once the placement is
          // known, then waits for these transitions before it unmounts the panel.
          "origin-(--trigger-anchor-point) transition-[opacity,scale,translate] duration-200 ease-[cubic-bezier(0.23,1,0.32,1)]",
          "placement-top:[--popover-shift:0_0.25rem] placement-bottom:[--popover-shift:0_-0.25rem] placement-left:[--popover-shift:0.25rem_0] placement-right:[--popover-shift:-0.25rem_0]",
          "entering:opacity-0 motion-safe:entering:scale-96 motion-safe:entering:[translate:var(--popover-shift)]",
          "exiting:opacity-0 exiting:duration-150 motion-safe:exiting:scale-98 motion-safe:exiting:[translate:var(--popover-shift)]",
          className,
        ),
      )}
    />
  );
}

export function PopoverArrow({
  className,
  ...props
}: Omit<OverlayArrowProps, "children">) {
  return (
    <OverlayArrow
      {...props}
      data-slot="popover-arrow"
      className={composeRenderProps(className, (className) =>
        cn("group/arrow", className),
      )}
    >
      <svg
        width={12}
        height={12}
        viewBox="0 0 12 12"
        aria-hidden="true"
        className="block fill-popover stroke-border group-placement-bottom/arrow:rotate-180 group-placement-left/arrow:-rotate-90 group-placement-right/arrow:rotate-90 forced-colors:fill-[Canvas] forced-colors:stroke-[CanvasText]"
      >
        <path d="M0 0 6 6 12 0" />
      </svg>
    </OverlayArrow>
  );
}

export function PopoverDialog({ className, ...props }: AriaDialogProps) {
  return (
    <AriaDialog
      {...props}
      data-slot="popover-dialog"
      className={cn("outline-none", className)}
    />
  );
}

export function PopoverTitle({ className, ...props }: HeadingProps) {
  return (
    <Heading
      {...props}
      slot="title"
      data-slot="popover-title"
      className={cn(
        "text-sm font-semibold leading-5 tracking-[-0.01em] [overflow-wrap:anywhere]",
        className,
      )}
    />
  );
}

export function PopoverDescription({ className, ...props }: TextProps) {
  return (
    <Text
      {...props}
      slot="description"
      data-slot="popover-description"
      className={cn(
        "mt-1 block text-sm leading-5 text-muted-foreground [overflow-wrap:anywhere]",
        className,
      )}
    />
  );
}

export function PopoverFooter({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      {...props}
      data-slot="popover-footer"
      className={cn("mt-4 flex flex-wrap justify-end gap-2", className)}
    />
  );
}

"use client";

import { CaretRightIcon } from "@phosphor-icons/react";
import { useSyncExternalStore } from "react";
import {
  Menu as AriaMenu,
  MenuItem as AriaMenuItem,
  composeRenderProps,
  type MenuItemProps,
  type MenuProps,
  MenuTrigger,
  PopoverContext,
  Separator,
  type SeparatorProps,
  SubmenuTrigger,
  useSlottedContext,
} from "react-aria-components";
import { cn } from "./utils";
import { SelectionMark } from "./list-box";
import { Popover } from "./popover";

export { MenuTrigger, SubmenuTrigger };

const narrowQuery = "(max-width: 639px)";

function subscribeToNarrow(onChange: () => void) {
  const media = window.matchMedia(narrowQuery);
  media.addEventListener("change", onChange);
  return () => media.removeEventListener("change", onChange);
}

function isNarrowViewport() {
  return window.matchMedia(narrowQuery).matches;
}

export function Menu<T extends object>({ className, ...props }: MenuProps<T>) {
  return (
    <MenuPopover>
      <MenuContent {...props} className={className} />
    </MenuPopover>
  );
}

export function MenuPopover({
  className,
  children,
  ...props
}: React.ComponentProps<typeof Popover>) {
  const context = useSlottedContext(PopoverContext, props.slot);
  const isSubmenu = context?.trigger === "SubmenuTrigger";
  const isNarrow = useSyncExternalStore(
    subscribeToNarrow,
    isNarrowViewport,
    () => false,
  );
  const stacked = isSubmenu && isNarrow;
  return (
    <Popover
      {...props}
      data-slot="menu-popover"
      placement={props.placement ?? (stacked ? "bottom end" : undefined)}
      offset={
        props.offset ?? context?.offset ?? (isSubmenu ? (stacked ? 4 : -2) : 7)
      }
      crossOffset={
        props.crossOffset ?? (isSubmenu && !stacked ? -6 : undefined)
      }
      maxHeight={props.maxHeight ?? 300}
      className={composeRenderProps(className, (className) =>
        cn(
          "min-w-[min(11rem,calc(100vw-2rem))] rounded-lg border-0 p-1.5 ring-1 ring-border/70",
          className,
        ),
      )}
    >
      {children}
    </Popover>
  );
}

export function MenuContent<T extends object>({
  className,
  ...props
}: MenuProps<T>) {
  return (
    <AriaMenu
      {...props}
      data-slot="menu-content"
      className={composeRenderProps(className, (className) =>
        cn("grid gap-1 outline-none [overflow-wrap:anywhere]", className),
      )}
    />
  );
}

export function MenuItem<T extends object>({
  className,
  children,
  ...props
}: MenuItemProps<T>) {
  return (
    <AriaMenuItem
      {...props}
      textValue={
        props.textValue ?? (typeof children === "string" ? children : undefined)
      }
      data-slot="menu-item"
      className={composeRenderProps(className, (className) =>
        cn(
          "flex min-h-11 cursor-pointer items-center gap-2.5 rounded-md px-3 py-2 text-sm text-foreground outline-none hover:bg-muted focus:bg-muted open:bg-muted focus-visible:-outline-offset-1 focus-visible:outline-1 focus-visible:outline-solid focus-visible:outline-ring forced-colors:focus-visible:-outline-offset-2 forced-colors:focus-visible:outline-2 selected:bg-accent selected:text-accent-foreground disabled:cursor-default disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&>[data-slot=kbd]]:ms-auto",
          className,
        ),
      )}
    >
      {composeRenderProps(
        children,
        (content, { isSelected, selectionMode, hasSubmenu }) => (
          <>
            {content}
            {selectionMode !== "none" && !hasSubmenu && (
              <SelectionMark isSelected={isSelected} />
            )}
            {hasSubmenu && (
              <CaretRightIcon
                size={16}
                aria-hidden="true"
                className="ms-auto text-muted-foreground rtl:rotate-180"
              />
            )}
          </>
        ),
      )}
    </AriaMenuItem>
  );
}

export function MenuSeparator({ className, ...props }: SeparatorProps) {
  return (
    <Separator
      {...props}
      data-slot="menu-separator"
      className={cn("border-t border-border/70", className)}
    />
  );
}

"use client";

import {
  MenuTrigger as AriaMenuTrigger,
  type MenuTriggerProps,
} from "react-aria-components";

export {
  Menu as ContextMenu,
  MenuContent as ContextMenuContent,
  MenuItem as ContextMenuItem,
  MenuPopover as ContextMenuPopover,
  MenuSeparator as ContextMenuSeparator,
} from "./menu";

export function ContextMenuTrigger(props: Omit<MenuTriggerProps, "trigger">) {
  return <AriaMenuTrigger {...props} trigger="contextMenu" />;
}
